    def __len__(self):
      if self.test:
        return len(self.data)
      else:
        return len(self.data) * 25
      

    def processing(self,idx, height=1024, width=1024, crop_size=200):

      xy = idx//len(self.data)
      randx = xy//5
      randy = xy%5

      idx = idx%len(self.data)

      if(self.test):
        img_path = os.path.join(self.data_dir, self.data.iloc[idx, 1])
        image = cv2.imread(img_path)
        image = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)

        return image

      img_path = os.path.join(self.data_dir, self.data.iloc[idx, 1])

      image = cv2.imread(img_path)
      image = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)

      mask_rle = self.data.iloc[idx, 2]
      mask = rle_decode(mask_rle, (image.shape[0], image.shape[1]))

      left = crop_size * (randx)
      top = crop_size * (randy)

      right = left + 224
      bottom = top + 224

      cropped_image = image[top:bottom, left:right, :]
      cropped_mask = mask[top:bottom, left:right]

      return cropped_image, cropped_mask


    def __getitem__(self, idx):
        if (self.test):
            image = self.processing(idx)
            if self.transform:
                image = self.transform(image=image)['image']
            return dict(image=image)

        image, mask = self.processing(idx)
        if self.transform:
            augmented = self.transform(image=image, mask=mask)
            image = augmented['image']
            mask = augmented['mask']

        batch = dict(
            image=image,
            mask=mask,
        )

        return batch
